async function inspectPages() {
  const pages = figma.root.children;
  const result = {};

  for (const page of pages) {
    await page.loadAsync();
    const textNodes = page.findAllWithCriteria({ types: ['TEXT'] });
    const texts = textNodes.map(t => `${t.name}: ${t.characters}`).slice(0, 50); // limit
    const topNodes = page.children.map(c => ({ id: c.id, name: c.name, type: c.type }));
    result[page.name] = { id: page.id, topNodes, textSample: texts };
  }

  return JSON.stringify(result, null, 2);
}
return await inspectPages();

async function getMediaAndComponents() {
  const pages = figma.root.children;
  const componentsPage = pages.find(p => p.name.includes('02'));
  const mediaPage = pages.find(p => p.name.includes('04'));
  const foundPage = pages.find(p => p.name.includes('01'));

  await componentsPage?.loadAsync();
  await mediaPage?.loadAsync();
  await foundPage?.loadAsync();

  function dumpNode(node) {
    return {
      id: node.id,
      name: node.name,
      type: node.type,
      width: node.width,
      height: node.height,
      children: 'children' in node ? node.children.map(c => dumpNode(c)) : undefined
    };
  }

  return JSON.stringify({
    components: componentsPage ? dumpNode(componentsPage) : null,
    media: mediaPage ? dumpNode(mediaPage) : null,
    foundations: foundPage ? dumpNode(foundPage) : null,
  }, null, 2);
}
return await getMediaAndComponents();

async function inspectMediaDetails() {
  const mediaPage = figma.root.children.find(p => p.name.includes('04'));
  await mediaPage.loadAsync();

  const compList = mediaPage.findAllWithCriteria({ types: ['COMPONENT'] });
  const compInfo = compList.map(c => ({
    id: c.id,
    name: c.name,
    width: c.width,
    height: c.height
  }));

  const compPage = figma.root.children.find(p => p.name.includes('02'));
  await compPage.loadAsync();
  const compList2 = compPage.findAllWithCriteria({ types: ['COMPONENT'] });
  const compInfo2 = compList2.map(c => ({
    id: c.id,
    name: c.name,
    width: c.width,
    height: c.height
  }));

  return JSON.stringify({ mediaComponents: compInfo, givenComponents: compInfo2 }, null, 2);
}
return await inspectMediaDetails();

