async function inspectComponentProperties() {
  const compPage = figma.root.children.find(p => p.name.includes('02'));
  await compPage.loadAsync();
  const button = compPage.findOne(n => n.name === 'Button' && n.type === 'COMPONENT');
  const textField = compPage.findOne(n => n.name === 'Text Field' && n.type === 'COMPONENT');
  const statusBar = compPage.findOne(n => n.name === 'Status Bar' && n.type === 'COMPONENT');
  const homeInd = compPage.findOne(n => n.name === 'Home Indicator' && n.type === 'COMPONENT');

  function getProps(n) {
    if (!n) return null;
    return {
      id: n.id,
      name: n.name,
      width: n.width,
      height: n.height,
      fills: n.fills,
      strokes: n.strokes,
      strokeWeight: n.strokeWeight,
      cornerRadius: n.cornerRadius,
      effects: n.effects,
      layoutMode: n.layoutMode,
      paddingLeft: n.paddingLeft,
      paddingRight: n.paddingRight,
      paddingTop: n.paddingTop,
      paddingBottom: n.paddingBottom,
      children: n.children ? n.children.map(c => ({
        id: c.id,
        name: c.name,
        type: c.type,
        fills: c.fills,
        characters: c.characters,
        fontSize: c.fontSize,
        fontName: c.fontName
      })) : []
    };
  }

  return JSON.stringify({
    button: getProps(button),
    textField: getProps(textField),
    statusBar: getProps(statusBar),
    homeInd: getProps(homeInd)
  }, null, 2);
}
return await inspectComponentProperties();

