async function buildTravelinDesign() {
  // 1. Get workspace page and reference pages
  const pages = figma.root.children;
  let workspace = pages.find(p => p.name.includes('03'));
  if (!workspace) {
    workspace = figma.createPage();
    workspace.name = '03 · Workspace';
  }
  await figma.setCurrentPageAsync(workspace);

  // Clear workspace existing children to ensure clean state
  for (const child of workspace.children) {
    child.remove();
  }

  // Load fonts
  await figma.loadFontAsync({ family: 'Inter', style: 'Regular' });
  await figma.loadFontAsync({ family: 'Inter', style: 'Medium' });
  await figma.loadFontAsync({ family: 'Inter', style: 'Semi Bold' });
  await figma.loadFontAsync({ family: 'Inter', style: 'Bold' });

  // Get master component references
  const compPage = pages.find(p => p.name.includes('02'));
  const mediaPage = pages.find(p => p.name.includes('04'));
  await compPage?.loadAsync();
  await mediaPage?.loadAsync();

  const getComp = (name, page) => {
    return page.findOne(n => n.name === name && (n.type === 'COMPONENT' || n.type === 'FRAME'));
  };

  const masterLogo = mediaPage.findOne(n => n.name === 'Logo_Travelin' && n.type === 'COMPONENT');
  const masterPhotoAerial = mediaPage.findOne(n => n.name === 'Photo_Aerial_Island' && n.type === 'COMPONENT');
  const masterPhotoBalloons = mediaPage.findOne(n => n.name === 'Photo_Hot_Air_Balloons' && n.type === 'COMPONENT');
  const masterPhotoAvatar = mediaPage.findOne(n => n.name === 'Photo_Avatar_Cat' && n.type === 'COMPONENT');
  const masterPhotoHotel = mediaPage.findOne(n => n.name === 'Photo_Hotel_Room' && n.type === 'COMPONENT');
  const masterPhotoBromo = mediaPage.findOne(n => n.name === 'Photo_Mount_Bromo' && n.type === 'COMPONENT');
  const masterPhotoLabengki = mediaPage.findOne(n => n.name === 'Photo_Labengki_Sombori' && n.type === 'COMPONENT');
  const masterPhotoKomodo = mediaPage.findOne(n => n.name === 'Photo_Sailing_Komodo' && n.type === 'COMPONENT');

  const masterIconPlane = mediaPage.findOne(n => n.name === 'Icon_Plane' && n.type === 'COMPONENT');
  const masterIconChevronDown = mediaPage.findOne(n => n.name === 'Icon_Chevron_Down' && n.type === 'COMPONENT');
  const masterIconApple = mediaPage.findOne(n => n.name === 'Icon_Apple' && n.type === 'COMPONENT');
  const masterIconFacebook = mediaPage.findOne(n => n.name === 'Icon_Facebook' && n.type === 'COMPONENT');
  const masterIconGoogle = mediaPage.findOne(n => n.name === 'Icon_Google' && n.type === 'COMPONENT');
  const masterIconCoin = mediaPage.findOne(n => n.name === 'Icon_Coin' && n.type === 'COMPONENT');
  const masterIconSearch = mediaPage.findOne(n => n.name === 'Icon_Search' && n.type === 'COMPONENT');
  const masterIconFlight = mediaPage.findOne(n => n.name === 'Icon_Flight' && n.type === 'COMPONENT');
  const masterIconHotel = mediaPage.findOne(n => n.name === 'Icon_Hotel' && n.type === 'COMPONENT');
  const masterIconTrain = mediaPage.findOne(n => n.name === 'Icon_Train' && n.type === 'COMPONENT');
  const masterIconFerry = mediaPage.findOne(n => n.name === 'Icon_Ferry' && n.type === 'COMPONENT');
  const masterIconBus = mediaPage.findOne(n => n.name === 'Icon_Bus' && n.type === 'COMPONENT');
  const masterIconStar = mediaPage.findOne(n => n.name === 'Icon_Star' && n.type === 'COMPONENT');
  const masterIconHome = mediaPage.findOne(n => n.name === 'Icon_Home' && n.type === 'COMPONENT');
  const masterIconTicket = mediaPage.findOne(n => n.name === 'Icon_Ticket' && n.type === 'COMPONENT');
  const masterIconDeals = mediaPage.findOne(n => n.name === 'Icon_Deals' && n.type === 'COMPONENT');
  const masterIconAccount = mediaPage.findOne(n => n.name === 'Icon_Account' && n.type === 'COMPONENT');
  const masterIconTakeoff = mediaPage.findOne(n => n.name === 'Icon_Takeoff' && n.type === 'COMPONENT');
  const masterIconLanding = mediaPage.findOne(n => n.name === 'Icon_Landing' && n.type === 'COMPONENT');

  const masterStatusBar = compPage.findOne(n => n.name === 'Status Bar' && n.type === 'COMPONENT');
  const masterHomeIndicator = compPage.findOne(n => n.name === 'Home Indicator' && n.type === 'COMPONENT');
  const masterButton = compPage.findOne(n => n.name === 'Button' && n.type === 'COMPONENT');
  const masterTextField = compPage.findOne(n => n.name === 'Text Field' && n.type === 'COMPONENT');

  // Helper to color vector children in instance or clone
  function recolorNode(node, colorObj) {
    if ('fills' in node && node.fills) {
      node.fills = [{ type: 'SOLID', color: colorObj }];
    }
    if ('children' in node) {
      for (const child of node.children) {
        recolorNode(child, colorObj);
      }
    }
  }

  // Create UI Status Bar helper
  function createStatusBar(isWhite = false) {
    let inst = masterStatusBar.createInstance();
    if (isWhite) {
      recolorNode(inst, { r: 1, g: 1, b: 1 });
    }
    return inst;
  }

  function createHomeIndicator(isWhite = false) {
    let inst = masterHomeIndicator.createInstance();
    if (isWhite) {
      recolorNode(inst, { r: 1, g: 1, b: 1 });
    }
    return inst;
  }

  // Brand Colors:
  // Teal Primary: #007A8C -> {r:0, g:0.4784, b:0.5490}
  // Forest Green Secondary: #336749 -> {r:0.2, g:0.4039, b:0.2863}
  const COLOR_TEAL = { r: 0, g: 0.47843137, b: 0.5490196 };
  const COLOR_GREEN = { r: 0.2, g: 0.40392157, b: 0.2862745 };
  const COLOR_WHITE = { r: 1, g: 1, b: 1 };
  const COLOR_DARK = { r: 0.10196, g: 0.10196, b: 0.12156 }; // #1A1A1F
  const COLOR_GRAY_TEXT = { r: 0.54117, g: 0.5647, b: 0.59215 };
  const COLOR_LIGHT_BG = { r: 0.96078, g: 0.9686, b: 0.97647 }; // #F5F7F9
  const COLOR_BORDER = { r: 0.898, g: 0.91, b: 0.925 };
  const COLOR_GOLD = { r: 0.96, g: 0.65, b: 0.13 }; // Star rating

  // =========================================================================
  // FRAME 1: 01_Splash
  // =========================================================================
  const frameSplash = figma.createFrame();
  frameSplash.name = '01_Splash';
  frameSplash.resize(430, 932);
  frameSplash.x = 0;
  frameSplash.y = 0;
  frameSplash.fills = [{ type: 'SOLID', color: COLOR_TEAL }];
  frameSplash.clipsContent = true;

  // Status bar & Home ind
  const sb1 = createStatusBar(true);
  sb1.x = 0; sb1.y = 0;
  frameSplash.appendChild(sb1);

  const hi1 = createHomeIndicator(true);
  hi1.x = 0; hi1.y = 932 - 34;
  frameSplash.appendChild(hi1);

  // Center container for Logo + Tagline
  const splashContent = figma.createFrame();
  splashContent.name = 'Splash Content';
  splashContent.layoutMode = 'VERTICAL';
  splashContent.primaryAxisAlignItems = 'CENTER';
  splashContent.counterAxisAlignItems = 'CENTER';
  splashContent.itemSpacing = 20;
  splashContent.fills = [];
  splashContent.resize(360, 150);
  splashContent.x = (430 - 360) / 2;
  splashContent.y = (932 - 150) / 2 - 20;

  const logo1 = masterLogo.createInstance();
  splashContent.appendChild(logo1);

  const tagline = figma.createText();
  tagline.fontName = { family: 'Inter', style: 'Medium' };
  tagline.fontSize = 15;
  tagline.characters = 'Your Passport to Seamless Adventures!';
  tagline.fills = [{ type: 'SOLID', color: COLOR_WHITE }];
  tagline.textAlignHorizontal = 'CENTER';
  splashContent.appendChild(tagline);

  frameSplash.appendChild(splashContent);

  // =========================================================================
  // FRAME 2: 02_Get_Started
  // =========================================================================
  const frameGetStarted = figma.createFrame();
  frameGetStarted.name = '02_Get_Started';
  frameGetStarted.resize(430, 932);
  frameGetStarted.x = 500;
  frameGetStarted.y = 0;
  frameGetStarted.fills = [{ type: 'SOLID', color: COLOR_TEAL }];
  frameGetStarted.clipsContent = true;

  // Background Photo (Photo_Aerial_Island) stretched/cropped
  const photoAerialInst = masterPhotoAerial.createInstance();
  photoAerialInst.resize(430, 932);
  photoAerialInst.x = 0; photoAerialInst.y = 0;
  frameGetStarted.appendChild(photoAerialInst);

  // Dark / Teal Gradient Overlay for readability
  const overlay1 = figma.createRectangle();
  overlay1.resize(430, 932);
  overlay1.fills = [{
    type: 'GRADIENT_LINEAR',
    gradientTransform: [[0, 1, 0], [-1, 0, 1]], // top to bottom
    gradientStops: [
      { position: 0, color: { r: 0, g: 0.3, b: 0.35, a: 0.4 } },
      { position: 0.5, color: { r: 0, g: 0.2, b: 0.25, a: 0.3 } },
      { position: 1, color: { r: 0, g: 0.15, b: 0.2, a: 0.85 } }
    ]
  }];
  frameGetStarted.appendChild(overlay1);

  // Status Bar
  const sb2 = createStatusBar(true);
  sb2.x = 0; sb2.y = 0;
  frameGetStarted.appendChild(sb2);

  // Language Selector Top Right: "English" (Icon_Chevron_Down)
  const langBar2 = figma.createFrame();
  langBar2.name = 'Language Selector';
  langBar2.layoutMode = 'HORIZONTAL';
  langBar2.counterAxisAlignItems = 'CENTER';
  langBar2.itemSpacing = 6;
  langBar2.paddingLeft = 14; langBar2.paddingRight = 14;
  langBar2.paddingTop = 8; langBar2.paddingBottom = 8;
  langBar2.cornerRadius = 20;
