    tabLabel.fills = [{ type: 'SOLID', color: t.active ? COLOR_TEAL : COLOR_GRAY_TEXT }];
    tabItem.appendChild(tabLabel);

    tabBar.appendChild(tabItem);
  }

  frameHome.appendChild(tabBar);

  const hi4 = createHomeIndicator(false);
  hi4.x = 0; hi4.y = 932 - 34;
  frameHome.appendChild(hi4);

  // =========================================================================
  // PROTOTYPE CONNECTIONS
  // =========================================================================
  frameSplash.reactions = [{
    trigger: { type: 'AFTER_TIMEOUT', timeout: 1.5 },
    actions: [{
      type: 'NODE',
      destinationId: frameGetStarted.id,
      navigation: 'NAVIGATE',
      transition: null
    }]
  }];

  btn2.reactions = [{
    trigger: { type: 'ON_CLICK' },
    actions: [{
      type: 'NODE',
      destinationId: frameSignIn.id,
      navigation: 'NAVIGATE',
      transition: null
    }]
  }];

  btnSignIn.reactions = [{
    trigger: { type: 'ON_CLICK' },
    actions: [{
      type: 'NODE',
      destinationId: frameHome.id,
      navigation: 'NAVIGATE',
      transition: null
    }]
  }];

  return JSON.stringify({
    splashId: frameSplash.id,
    getStartedId: frameGetStarted.id,
    signInId: frameSignIn.id,
    homeId: frameHome.id
  });
}
return await buildTravelinDesignFinal();
